export interface DatePickerProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
}

export function DatePicker({
  label,
  value,
  onChange,
}: DatePickerProps) {
  return (
    <label>
      <span>{label}</span>
      <input
        type="date"
        value={value}
        onChange={(event) => onChange(event.currentTarget.value)}
      />
    </label>
  );
}

export default DatePicker;

Implemented the accessible controlled date picker in `date_picker/DatePicker.tsx` with a label, date input, string value, and `onChange` callback.
